<div class="page-title"><div><h2>کمیسیون فروش</h2></div></div><section class="card"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>قرارداد</th><th>فروشنده</th><th>مبنای محاسبه</th><th>مبلغ کمیسیون</th><th>وضعیت</th></tr></thead><tbody><?php foreach (($commissions ?? []) as $commission): ?><tr><td><?= e($commission['contract_number']) ?></td><td><?= e($commission['seller_name'] ?: 'تخصیص نشده') ?></td><td><?= money_toman($commission['basis_amount']) ?> / <?= e($commission['basis_type']) ?></td><td><?= money_toman($commission['calculated_amount']) ?></td><td><?= e($commission['status']) ?></td></tr><?php endforeach; ?><?php if (empty($commissions)): ?><tr><td colspan="5" class="empty">کمیسیونی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></section>
